def clz(x, bits):
    n = 0
    for i in range(bits - 1, -1, -1):
        if (x >> i) & 1: break
        n += 1
    return n

def lowest_set(x, bits):
    for i in range(bits):
        if (x >> i) & 1: return 1 << i
    return 0

def reverse(x, bits):
    r = 0
    for i in range(bits):
        r = (r << 1) | ((x >> i) & 1)
    return r

def add_overflows(a, b, bits):
    lo, hi = -(1 << (bits-1)), (1 << (bits-1)) - 1
    return not (lo <= a + b <= hi)   # unbounded ints in the reference
